use pr_core::abstractions::{AppendStream, Clock, FileStat, FileSystem, ReadSeek, RecycleBin};
use pr_core::catalog::types::CaptureGroup;
use pr_core::file_actions::journal::{OperationJournal, OperationJournalOptions};
use pr_core::file_actions::journal_line::JournalEntry;
use pr_core::file_actions::service::FileActionService;
use pr_core::file_actions::types::{
    CaptureGroupActionRequest, CaptureGroupActionResult, FileActionRequest, FileActionResult,
};
use pr_core::file_actions::undo::MoveOverride;
use pr_core::model::FileOperationType;
use pr_core::sync::CancelToken;
use pr_core::text::dotnet_path::get_directory_name;
use pr_core::text::{cmp_ignore_case, eq_ignore_case, ignore_case_key};
use pr_core::time::{DateTimeUtc, TICKS_PER_SECOND};
use pr_test_support::{FakeClock, golden};
use serde_json::{Value, json};

/// OrdinalIgnoreCase dictionary key of a path (C# `StringComparer.OrdinalIgnoreCase`).
fn key(path: &str) -> String {
    ignore_case_key(path)
}

/// `W304Faults`: the scenario's faults (all optional). Keys are OrdinalIgnoreCase.
#[derive(Default, Clone)]
struct Faults {
    move_fail: HashMap<String, String>,
    move_leaves_source: HashSet<String>,
    move_truncate: HashMap<String, usize>,
    move_round_2s: bool,
    copy_fail: HashMap<String, String>,
    copy_partial: HashMap<String, (usize, String)>,
    copy_size: HashMap<String, usize>,
    copy_then_cancel: HashSet<String>,
    foreign_on_copy: HashMap<String, usize>,
    delete_fail: HashMap<String, String>,
    append_fail: HashSet<usize>,
    no_bin_roots: Vec<String>,
    bin_capacity: Vec<(String, u64)>,
    recycle_fail: HashMap<String, String>,
    recycle_leaves: HashSet<String>,
    permanent_fail: HashMap<String, String>,
    permanent_leaves: HashSet<String>,
    cancel_on: Option<(String, String)>,
}

/// `W304ParseFaults`.
fn parse_faults(case: &Value) -> Faults {
    let mut faults = Faults::default();
    let Some(object) = case.get("faults").and_then(Value::as_object) else {
        return faults;
    };
    let paths = |v: &Value| -> HashSet<String> {
        v.as_array()
            .map(|a| a.iter().filter_map(Value::as_str).map(key).collect())
            .unwrap_or_default()
    };
    let messages = |v: &Value| -> HashMap<String, String> {
        v.as_object()
            .map(|o| {
                o.iter()
                    .map(|(p, m)| (key(p), m.as_str().expect("fault message").to_owned()))
                    .collect()
            })
            .unwrap_or_default()
    };
    let counts = |v: &Value| -> HashMap<String, usize> {
        v.as_object()
            .map(|o| {
                o.iter()
                    .map(|(p, n)| {
                        (
                            key(p),
                            usize::try_from(n.as_u64().expect("count")).expect("small count"),
                        )
                    })
                    .collect()
            })
            .unwrap_or_default()
    };
    for (name, value) in object {
        match name.as_str() {
            "move_fail" => faults.move_fail = messages(value),
            "move_leaves_source" => faults.move_leaves_source = paths(value),
            "move_truncate" => faults.move_truncate = counts(value),
            "move_round_2s" => faults.move_round_2s = value.as_bool().expect("bool"),
            "copy_fail" => faults.copy_fail = messages(value),
            "copy_partial" => {
                faults.copy_partial = value
                    .as_object()
                    .expect("copy_partial object")
                    .iter()
                    .map(|(p, v)| {
                        let bytes = usize::try_from(v["bytes"].as_u64().expect("bytes")).expect("small");
                        (key(p), (bytes, v["message"].as_str().expect("message").to_owned()))
                    })
                    .collect();
            }
            "copy_size" => faults.copy_size = counts(value),
            "copy_then_cancel" => faults.copy_then_cancel = paths(value),
            "foreign_on_copy" => faults.foreign_on_copy = counts(value),
            "delete_fail" => faults.delete_fail = messages(value),
            "append_fail" => {
                faults.append_fail = value
                    .as_array()
                    .expect("append_fail array")
                    .iter()
                    .map(|n| usize::try_from(n.as_u64().expect("index")).expect("small"))
                    .collect();
            }
            "no_bin_roots" => {
                faults.no_bin_roots = value
                    .as_array()
                    .expect("no_bin_roots array")
                    .iter()
                    .map(|r| r.as_str().expect("root").to_owned())
                    .collect();
            }
            "bin_capacity" => {
                faults.bin_capacity = value
                    .as_object()
                    .expect("bin_capacity object")
                    .iter()
                    .map(|(r, b)| (r.clone(), b.as_u64().expect("capacity")))
                    .collect();
            }
            "recycle_fail" => faults.recycle_fail = messages(value),
            "recycle_leaves" => faults.recycle_leaves = paths(value),
            "permanent_fail" => faults.permanent_fail = messages(value),
            "permanent_leaves" => faults.permanent_leaves = paths(value),
            "cancel_on" => {
                faults.cancel_on = Some((
                    value["op"].as_str().expect("op").to_owned(),
                    value["path"].as_str().expect("path").to_owned(),
                ));
            }
            other => panic!("golden fault key not handled by the harness: {other}"),
        }
    }
    faults
}

/// C# `path.StartsWith(root, StringComparison.OrdinalIgnoreCase)`.
fn starts_with_ignore_case(path: &str, root: &str) -> bool {
    key(path).starts_with(&key(root))
}

/// One file of the disk (C# `Entry(Path, Data, Stamp)`): `path` keeps the spelling it was created with.
#[derive(Clone)]
struct Entry {
    path: String,
    data: Vec<u8>,
    stamp: DateTimeUtc,
}

#[derive(Default)]
struct DiskState {
    files: HashMap<String, Entry>,
    /// key => the folder text as it was added.
    dirs: HashMap<String, String>,
    trace: Vec<String>,
    appends: usize,
}

/// `W304Disk.Key`: a path longer than 3 chars loses its trailing separators.
fn disk_key(path: &str) -> String {
    if path.chars().count() > 3 {
        path.trim_end_matches(['\\', '/']).to_owned()
    } else {
        path.to_owned()
    }
}

/// `W304Disk.Parent`: `Path.GetDirectoryName(Key(path))`.
fn parent(path: &str) -> Option<String> {
    get_directory_name(&disk_key(path))
}

/// The oracle's clock (`W304Now`, 2026-10-01T00:00:00Z).
fn now() -> DateTimeUtc {
    stamp(CLOCK_TICKS)
}

/// `W304Disk`: the oracle's in-memory disk, with the case's faults; traces every mutating call.
struct ScenarioFs {
    state: Arc<Mutex<DiskState>>,
    faults: Faults,
    cancel: CancelToken,
    journal_file: String,
    journal_dir: String,
}

impl ScenarioFs {
    fn new(faults: Faults, cancel: CancelToken) -> Self {
        let journal_file = journal_path();
        let journal_dir = get_directory_name(&journal_file).expect("journal folder");
        let fs = Self {
            state: Arc::new(Mutex::new(DiskState::default())),
            faults,
            cancel,
            journal_file,
            journal_dir,
        };
        let dir = fs.journal_dir.clone();
        fs.add_dirs(&dir);
        fs
    }

    fn lock(&self) -> MutexGuard<'_, DiskState> {
        self.state.lock().unwrap_or_else(PoisonError::into_inner)
    }

    /// `AddDirs`: the folder and every parent.
    fn add_dirs(&self, dir: &str) {
        let mut state = self.lock();
        add_dirs_locked(&mut state, dir);
    }

    /// `AddFile`: `bytes` pattern bytes stamped `ticks`, parents created.
    fn add_file(&self, path: &str, bytes: usize, ticks: i64) {
        let mut state = self.lock();
        if let Some(p) = parent(path) {
            add_dirs_locked(&mut state, &p);
        }
        state.files.insert(
            key(&disk_key(path)),
            Entry {
                path: path.to_owned(),
                data: pattern_bytes(bytes),
                stamp: stamp(ticks),
            },
        );
    }

    /// `Note`: records the call (except the journal file and folder), then cancels the token when `cancel_on` names it.
    fn note(&self, op: &str, path: &str) {
        if eq_ignore_case(path, &self.journal_file) || eq_ignore_case(&disk_key(path), &self.journal_dir) {
            return;
        }
        self.lock().trace.push(format!("{op}:{path}"));
        if let Some((cancel_op, cancel_path)) = &self.faults.cancel_on {
            if cancel_op == op && eq_ignore_case(cancel_path, path) {
                self.cancel.cancel();
            }
        }
    }

    /// `Exists(destination)`.
    fn exists(destination: &str) -> io::Error {
        io::Error::new(
            io::ErrorKind::AlreadyExists,
            format!("The file '{destination}' already exists."),
        )
    }

    /// `Missing(path)`: `FileNotFoundException`.
    fn missing(path: &str) -> io::Error {
        io::Error::new(io::ErrorKind::NotFound, format!("Could not find file '{path}'."))
    }

    /// `RequireParent`: `DirectoryNotFoundException`.
    fn require_parent(state: &DiskState, path: &str) -> io::Result<()> {
        match parent(path) {
            Some(p) if !state.dirs.contains_key(&key(&disk_key(&p))) => Err(io::Error::new(
                io::ErrorKind::NotFound,
                format!("Could not find a part of the path '{path}'."),
            )),
            _ => Ok(()),
        }
    }

    /// `Remove` (the bin's removal: no trace).
    fn remove(&self, path: &str) {
        self.lock().files.remove(&key(&disk_key(path)));
    }

    fn files_json(&self) -> Vec<Value> {
        let state = self.lock();
        let mut files: Vec<&Entry> = state
            .files
            .values()
            .filter(|e| !eq_ignore_case(&e.path, &self.journal_file))
            .collect();
        files.sort_by(|a, b| cmp_ignore_case(&a.path, &b.path));
        files
            .into_iter()
            .map(|e| json!({"path": e.path, "size": e.data.len(), "ticks": e.stamp.ticks().to_string()}))
            .collect()
    }

    fn journal_text(&self) -> String {
        self.lock()
            .files
            .get(&key(&disk_key(&self.journal_file)))
            .map(|e| String::from_utf8(e.data.clone()).expect("UTF-8 journal"))
            .unwrap_or_default()
    }

    fn trace(&self) -> Vec<String> {
        self.lock().trace.clone()
    }

    fn directory_exists_text(&self, path: &str) -> bool {
        self.lock().dirs.contains_key(&key(&disk_key(path)))
    }
}

fn add_dirs_locked(state: &mut DiskState, dir: &str) {
    let mut current = Some(disk_key(dir));
    while let Some(d) = current {
        if d.is_empty() {
            break;
        }
        let k = disk_key(&d);
        state.dirs.entry(key(&k)).or_insert(k);
        current = get_directory_name(&d);
    }
}

fn text(path: &Path) -> String {
    path.to_string_lossy().into_owned()
}

impl FileSystem for ScenarioFs {
    fn file_exists(&self, path: &Path) -> bool {
        self.lock().files.contains_key(&key(&disk_key(&text(path))))
    }

    fn directory_exists(&self, path: &Path) -> bool {
        self.directory_exists_text(&text(path))
    }

    fn get_file_stat(&self, path: &Path) -> Option<FileStat> {
        self.lock().files.get(&key(&disk_key(&text(path)))).map(|e| FileStat {
            length: e.data.len() as u64,
            last_write_utc: e.stamp,
        })
    }

    fn move_file(&self, source: &Path, destination: &Path) -> io::Result<()> {
        let (source, destination) = (text(source), text(destination));
        self.note("move", &source);
        if let Some(message) = self.faults.move_fail.get(&key(&source)) {
            return Err(io::Error::other(message.clone()));
        }
        let mut state = self.lock();
        let Some(entry) = state.files.get(&key(&disk_key(&source))).cloned() else {
            return Err(Self::missing(&source));
        };
        if state.files.contains_key(&key(&disk_key(&destination))) {
            return Err(Self::exists(&destination));
        }
        Self::require_parent(&state, &destination)?;
        let mut data = entry.data.clone();
        if let Some(keep) = self.faults.move_truncate.get(&key(&source)) {
            data.truncate(*keep);
        }
        let stamp_utc = if self.faults.move_round_2s {
            let ticks = entry.stamp.ticks();
            stamp(ticks - ticks % (2 * TICKS_PER_SECOND))
        } else {
            entry.stamp
        };
        if !self.faults.move_leaves_source.contains(&key(&source)) {
            state.files.remove(&key(&disk_key(&source)));
        }
        state.files.insert(
            key(&disk_key(&destination)),
            Entry {
                path: destination,
                data,
                stamp: stamp_utc,
            },
        );
        Ok(())
    }

    fn copy_file(&self, source: &Path, destination: &Path) -> io::Result<()> {
        let (source, destination) = (text(source), text(destination));
        self.note("copy", &source);
        if let Some(message) = self.faults.copy_fail.get(&key(&source)) {
            return Err(io::Error::other(message.clone()));
        }
        let mut state = self.lock();
        let Some(entry) = state.files.get(&key(&disk_key(&source))).cloned() else {
            return Err(Self::missing(&source));
        };
        let destination_key = key(&disk_key(&destination));
        if let Some(foreign) = self.faults.foreign_on_copy.get(&key(&source)) {
            state.files.insert(
                destination_key,
                Entry {
                    path: destination.clone(),
                    data: vec![0; *foreign],
                    stamp: now(),
                },
            );
            return Err(Self::exists(&destination));
        }
        if state.files.contains_key(&destination_key) {
            return Err(Self::exists(&destination));
        }
        Self::require_parent(&state, &destination)?;
        if let Some((bytes, message)) = self.faults.copy_partial.get(&key(&source)) {
            let data = entry.data.iter().take(*bytes).copied().collect();
            state.files.insert(
                destination_key,
                Entry {
                    path: destination,
                    data,
                    stamp: now(),
                },
            );
            return Err(io::Error::other(message.clone()));
        }
        if self.faults.copy_then_cancel.contains(&key(&source)) {
            state.files.insert(
                destination_key,
                Entry {
                    path: destination,
                    data: entry.data.clone(),
                    stamp: entry.stamp,
                },
            );
            // C# `throw new OperationCanceledException()`: the token itself is NOT cancelled.
            return Err(canceled_error());
        }
        let data = match self.faults.copy_size.get(&key(&source)) {
            Some(size) => vec![0; *size],
            None => entry.data.clone(),
        };
        state.files.insert(
            destination_key,
            Entry {
                path: destination,
                data,
                stamp: entry.stamp,
            },
        );
        Ok(())
    }

    // `try_copy_new_with_proof` is NOT overridden: the trait default (file_exists, copy_file, mark_created) is the C#
    // interface default the oracle uses.

    fn delete(&self, path: &Path) -> io::Result<()> {
        let path = text(path);
        self.note("delete", &path);
        if let Some(message) = self.faults.delete_fail.get(&key(&path)) {
            return Err(io::Error::other(message.clone()));
        }
        self.remove(&path);
        Ok(())
    }

    fn open_read_shared(&self, path: &Path, _buffer_size: usize) -> io::Result<Box<dyn ReadSeek>> {
        let path = text(path);
        match self.lock().files.get(&key(&disk_key(&path))) {
            Some(e) => Ok(Box::new(Cursor::new(e.data.clone()))),
            None => Err(Self::missing(&path)),
        }
    }

    fn open_append(&self, path: &Path, _durable: bool) -> io::Result<Box<dyn AppendStream>> {
        let path = text(path);
        let mut state = self.lock();
        state.appends += 1;
        state.trace.push("append".to_owned());
        if self.faults.append_fail.contains(&state.appends) {
            return Err(io::Error::other("journal unavailable"));
        }
        Self::require_parent(&state, &path)?;
        let k = key(&disk_key(&path));
        state.files.entry(k.clone()).or_insert_with(|| Entry {
            path: path.clone(),
            data: Vec::new(),
            stamp: now(),
        });
        Ok(Box::new(ScenarioAppend {
            state: self.state.clone(),
            key: k,
            path,
        }))
    }

    fn write_all_text_atomic(&self, _path: &Path, _text: &str, _durable: bool) -> io::Result<()> {
        Err(io::Error::new(io::ErrorKind::Unsupported, "not used by W3-04"))
    }

    fn read_all_text(&self, path: &Path) -> io::Result<String> {
        let path = text(path);
        match self.lock().files.get(&key(&disk_key(&path))) {
            Some(e) => Ok(String::from_utf8_lossy(&e.data).into_owned()),
            None => Err(Self::missing(&path)),
        }
    }

    fn enumerate_files(&self, directory: &Path, _pattern: &str) -> io::Result<Vec<PathBuf>> {
        let directory = disk_key(&text(directory));
        Ok(self
            .lock()
            .files
            .values()
            .filter(|e| parent(&e.path).is_some_and(|p| eq_ignore_case(&p, &directory)))
            .map(|e| PathBuf::from(&e.path))
            .collect())
    }

    fn enumerate_directories(&self, directory: &Path) -> io::Result<Vec<PathBuf>> {
        let directory = disk_key(&text(directory));
        Ok(self
            .lock()
            .dirs
            .values()
            .filter(|d| parent(d).is_some_and(|p| eq_ignore_case(&p, &directory)))
            .map(PathBuf::from)
            .collect())
    }

    fn create_directory(&self, path: &Path) -> io::Result<()> {
        let path = text(path);
        self.note("mkdir", &disk_key(&path));
        let mut state = self.lock();
        if state.files.contains_key(&key(&disk_key(&path))) {
            return Err(io::Error::other(format!(
                "Cannot create '{path}' because a file with the same name already exists."
            )));
        }
        add_dirs_locked(&mut state, &path);
        Ok(())
    }

    fn try_delete_empty_directory(&self, path: &Path) -> bool {
        let path = text(path);
        self.note("rmdir", &disk_key(&path));
        let mut state = self.lock();
        let k = disk_key(&path);
        if !state.dirs.contains_key(&key(&k)) {
            return false;
        }
        if state
            .files
            .values()
            .any(|e| parent(&e.path).is_some_and(|p| eq_ignore_case(&p, &k)))
        {
            return false;
        }
        if state
            .dirs
            .values()
            .any(|d| !eq_ignore_case(d, &k) && parent(d).is_some_and(|p| eq_ignore_case(&p, &k)))
        {
            return false;
        }
        state.dirs.remove(&key(&k));
        true
    }
}

/// `W304Disk.AppendStream`: every write appends to the journal file and stamps it with the clock.
struct ScenarioAppend {
    state: Arc<Mutex<DiskState>>,
    key: String,
    path: String,
}

impl Write for ScenarioAppend {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let mut state = self.state.lock().unwrap_or_else(PoisonError::into_inner);
        let entry = state.files.entry(self.key.clone()).or_insert_with(|| Entry {
            path: self.path.clone(),
            data: Vec::new(),
            stamp: now(),
        });
        entry.data.extend_from_slice(buf);
        entry.stamp = now();
        Ok(buf.len())
    }

    fn flush(&mut self) -> io::Result<()> {
        Ok(())
    }
}

impl AppendStream for ScenarioAppend {}

/// `W304Bin`: the oracle's bin over [`ScenarioFs`] (never the real Recycle Bin).
struct ScenarioBin {
    disk: Arc<ScenarioFs>,
    faults: Faults,
    recycled: Mutex<Vec<String>>,
    permanently_deleted: Mutex<Vec<String>>,
    fits_calls: Mutex<Vec<Value>>,
}

impl ScenarioBin {
    fn new(disk: Arc<ScenarioFs>, faults: Faults) -> Self {
        Self {
            disk,
            faults,
            recycled: Mutex::new(Vec::new()),
            permanently_deleted: Mutex::new(Vec::new()),
            fits_calls: Mutex::new(Vec::new()),
        }
    }

    fn take(list: &Mutex<Vec<String>>) -> Vec<String> {
        list.lock().unwrap_or_else(PoisonError::into_inner).clone()
    }
}

impl RecycleBin for ScenarioBin {
    fn send_to_recycle_bin(&self, path: &Path) -> io::Result<()> {
        let path = text(path);
        self.disk.note("recycle", &path);
        if let Some(message) = self.faults.recycle_fail.get(&key(&path)) {
            return Err(io::Error::other(message.clone()));
        }
        if self.faults.recycle_leaves.contains(&key(&path)) {
            return Ok(()); // the shell reports success, the file stays (B-06)
        }
        if !self.disk.file_exists(Path::new(&path)) {
            return Err(ScenarioFs::missing(&path));
        }
        self.disk.remove(&path);
        self.recycled.lock().unwrap_or_else(PoisonError::into_inner).push(path);
        Ok(())
    }

    fn can_recycle(&self, path: &Path) -> bool {
        let path = text(path);
        !self
            .faults
            .no_bin_roots
            .iter()
            .any(|root| starts_with_ignore_case(&path, root))
    }

    fn delete_permanently(&self, path: &Path) -> io::Result<()> {
        let path = text(path);
        self.disk.note("permanent", &path);
        if let Some(message) = self.faults.permanent_fail.get(&key(&path)) {
            return Err(io::Error::other(message.clone()));
        }
        if self.faults.permanent_leaves.contains(&key(&path)) {
            return Ok(());
        }
        self.disk.remove(&path);
        self.permanently_deleted
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .push(path);
        Ok(())
    }

    fn try_restore(&self, _original_path: &Path, _expected_size: u64, _expected: DateTimeUtc) -> io::Result<bool> {
        Ok(false)
    }

    fn fits_in_recycle_bin(&self, path: &Path, file_size: u64) -> bool {
        let path = text(path);
        self.fits_calls
            .lock()
            .unwrap_or_else(PoisonError::into_inner)
            .push(json!({"path": path, "size": file_size}));
        for (root, capacity) in &self.faults.bin_capacity {
            if starts_with_ignore_case(&path, root) {
                return file_size <= *capacity;
            }
        }
        true
    }
}

/// C# `FileOperationType` name of the golden `op` string.
fn op_of(name: &str) -> FileOperationType {
    match name {
        "Move" => FileOperationType::Move,
        "Copy" => FileOperationType::Copy,
        "Recycle" => FileOperationType::Recycle,
        other => panic!("unknown golden op {other}"),
    }
}

/// Replaces each 32-hex GUID with `<idN>`, numbering in order of first appearance (C# `Regex.Replace(s, "[0-9a-f]{32}")`).
fn normalize_ids(text: &str, seen: &mut Vec<String>) -> String {
    let bytes = text.as_bytes();
    let mut out = String::new();
    let mut i = 0;
    while i < bytes.len() {
        let is_guid = i + 32 <= bytes.len()
            && bytes[i..i + 32]
                .iter()
                .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(b));
        if is_guid {
            let guid = text[i..i + 32].to_owned();
            let index = match seen.iter().position(|g| *g == guid) {
                Some(index) => index,
                None => {
                    seen.push(guid);
                    seen.len() - 1
                }
            };
            out.push_str(&format!("<id{}>", index + 1));
            i += 32;
        } else {
            let ch = text[i..].chars().next().expect("char boundary");
            out.push(ch);
            i += ch.len_utf8();
        }
    }
    out
}

fn opt(text: &Option<String>) -> Value {
    text.as_ref().map_or(Value::Null, |s| json!(s))
}

/// Runs one golden case and returns its observed values in the golden's shape (`FileActionScenarios`).
fn run_case(case: &Value) -> Value {
    let faults = parse_faults(case);
    let cancel = CancelToken::new();
    let disk = Arc::new(ScenarioFs::new(faults.clone(), cancel.clone()));
    for dir in case.get("dirs").and_then(Value::as_array).into_iter().flatten() {
        disk.add_dirs(dir.as_str().expect("dir"));
    }
    for file in case["files"].as_array().expect("files") {
        let ticks: i64 = file["ticks"]
            .as_str()
            .expect("ticks text")
            .parse()
            .expect("ticks number");
        let bytes = usize::try_from(file["bytes"].as_u64().expect("bytes")).expect("small file");
        disk.add_file(file["path"].as_str().expect("path"), bytes, ticks);
    }
    let bin = Arc::new(ScenarioBin::new(disk.clone(), faults));
    let clock: Arc<dyn Clock> = Arc::new(FakeClock::at(now()));
    let fs: Arc<dyn FileSystem> = disk.clone();
    let journal = Arc::new(OperationJournal::with_options(
        &fixture_paths(),
        fs.clone(),
        clock.clone(),
        OperationJournalOptions::default(),
    ));
    let mut service = FileActionService::new(journal, fs, clock, bin.clone());
    if let Some(mode) = case.get("move_override").and_then(Value::as_str) {
        // `W304MoveOverride`: the disk's (traced) move, then the failure.
        let disk_for_override = disk.clone();
        let mode = mode.to_owned();
        let override_fn: MoveOverride = Arc::new(move |source: &Path, destination: &Path| {
            disk_for_override.move_file(source, destination)?;
            match mode.as_str() {
                "move-then-cancel" => Err(canceled_error()),
                "move-then-fail" => Err(io::Error::other("override failed after the move")),
                other => Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    format!("unknown move_override {other}"),
                )),
            }
        });
        service = service.with_move_override(override_fn);
    }
    if case.get("pre_cancelled").and_then(Value::as_bool) == Some(true) {
        cancel.cancel();
    }

    let request = &case["request"];
    let operation = op_of(request["op"].as_str().expect("op"));
    let destination = request["destination"].as_str().map(str::to_owned);
    let allow_permanent = request["allow_permanent"].as_bool().unwrap_or(false);
    let result_json = if request["kind"] == "single" {
        let mut req = FileActionRequest::new(request["source"].as_str().expect("source"), operation);
        req.destination = destination;
        req.allow_permanent_delete = allow_permanent;
        let result: FileActionResult = service.execute(&req, &cancel);
        single_result_json(&result)
    } else {
        let capture = CaptureGroup::new(
            request["jpeg"].as_str().expect("jpeg"),
            request["raw"].as_str().expect("raw"),
            request["xmp"].as_str().map(str::to_owned),
        )
        .expect("golden group is valid");
        let mut req = CaptureGroupActionRequest::new(capture, operation);
        req.destination = destination;
        req.allow_permanent_delete = allow_permanent;
        let result: CaptureGroupActionResult = service.execute_group(&req, &cancel);
        group_result_json(&result)
    };

    // Journal lines first, so <idN> numbering follows the file.
    let mut seen_ids: Vec<String> = Vec::new();
    let journal_text = disk.journal_text();
    let journal_lines: Vec<String> = journal_text
        .split("\r\n")
        .filter(|l| !l.is_empty())
        .map(|l| normalize_ids(l, &mut seen_ids))
        .collect();
    let mut result_json = result_json;
    normalize_result_ids(&mut result_json, &mut seen_ids);

    let dirs_after: Vec<Value> = case
        .get("probe_dirs")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .map(|d| {
            let path = d.as_str().expect("probe dir");
            json!({"path": path, "exists": disk.directory_exists_text(path)})
        })
        .collect();

    json!({
        "result": result_json,
        "journal_lines": journal_lines,
        "journal_ends_with_crlf": journal_text.is_empty() || journal_text.ends_with("\r\n"),
        "files_after": disk.files_json(),
        "dirs_after": dirs_after,
        "recycled": ScenarioBin::take(&bin.recycled),
        "permanently_deleted_paths": ScenarioBin::take(&bin.permanently_deleted),
        "fits_calls": bin.fits_calls.lock().unwrap_or_else(PoisonError::into_inner).clone(),
        "trace": disk.trace(),
        "busy_after": service.is_busy(),
        "token_cancelled": cancel.is_canceled(),
    })
}

fn single_result_json(r: &FileActionResult) -> Value {
    json!({
        "succeeded": r.succeeded,
        "rejected": r.rejected,
        "operation": format!("{:?}", r.operation),
        "source": r.source,
        "destination_path": opt(&r.destination_path),
        "size": r.size,
        "last_write_ticks": r.last_write_utc.ticks().to_string(),
        "error": opt(&r.error),
        "journal_persisted": r.journal_persisted,
        "journal_error": opt(&r.journal_error),
        "permanently_deleted": r.permanently_deleted,
        "source_removed": r.source_removed,
    })
}

fn group_result_json(r: &CaptureGroupActionResult) -> Value {
    let members: Vec<Value> = r
        .members
        .iter()
        .map(|m| {
            json!({
                "source": m.member.source,
                "destination": opt(&m.member.destination),
                "size": m.member.size,
                "last_write_ticks": m.member.last_write_utc.value.ticks().to_string(),
                "permanent": m.member.permanent,
                "completed": m.completed,
                "conflict": m.conflict,
                "error": opt(&m.error),
                "source_exists": m.source_exists,
                "destination_exists": m.destination_exists,
                "state_known": m.state_known,
            })
        })
        .collect();
    json!({
        "succeeded": r.succeeded,
        "rejected": r.rejected,
        "operation": format!("{:?}", r.operation),
        "group_id": r.group_id,
        "entry": r.entry.as_ref().map_or(Value::Null, |e| entry_json_raw(e)),
        "members": members,
        "error": opt(&r.error),
        "journal_persisted": r.journal_persisted,
        "journal_error": opt(&r.journal_error),
        "permanently_deleted": r.permanently_deleted,
        "skipped_missing": r.skipped_missing.as_ref().map_or(Value::Null, |v| json!(v)),
    })
}

/// The entry without id normalization (normalized later together with the rest of the result).
fn entry_json_raw(entry: &JournalEntry) -> Value {
    json!({
        "id": entry.id,
        "state": format!("{:?}", entry.state),
        "source": entry.source,
        "destination": opt(&entry.destination),
        "error": opt(&entry.error),
        "error_code": opt(&entry.error_code),
        "permanent": entry.permanent.map_or(Value::Null, |p| json!(p)),
        "group_id": entry.group_id.clone().map_or(Value::Null, |g| json!(g)),
        "member_count": entry.group_members.as_ref().map_or(Value::Null, |m| json!(m.len())),
    })
}

/// Normalizes the GUIDs of a group result in the golden's order: `group_id`, then `entry.id`, `entry.group_id`.
fn normalize_result_ids(result: &mut Value, seen: &mut Vec<String>) {
    if let Some(group_id) = result.get("group_id").and_then(Value::as_str).map(str::to_owned) {
        result["group_id"] = json!(normalize_ids(&group_id, seen));
    }
    if let Some(entry) = result.get_mut("entry").and_then(Value::as_object_mut) {
        if let Some(id) = entry.get("id").and_then(Value::as_str).map(str::to_owned) {
            entry.insert("id".to_owned(), json!(normalize_ids(&id, seen)));
        }
        if let Some(group) = entry.get("group_id").and_then(Value::as_str).map(str::to_owned) {
            entry.insert("group_id".to_owned(), json!(normalize_ids(&group, seen)));
        }
    }
}

/// Every golden case, one after another: the first mismatch names the case and the field.
#[test]
fn file_action_scenarios_golden_all_cases_match_the_oracle() {
    let golden = golden::load("file-action-scenarios");
    assert_eq!(
        golden.cases.len(),
        111,
        "the golden has 111 cases (56 single, 55 group)"
    );
    let mut mismatches: Vec<String> = Vec::new();
    for case in &golden.cases {
        let name = case["name"].as_str().expect("case name");
        let observed = run_case(case);
        let expected = &case["expected"];
        for field in [
            "result",
            "journal_lines",
            "journal_ends_with_crlf",
            "files_after",
            "dirs_after",
            "recycled",
            "permanently_deleted_paths",
            "fits_calls",
            "trace",
            "busy_after",
            "token_cancelled",
        ] {
            if observed.get(field) != expected.get(field) {
                mismatches.push(format!(
                    "{name}: {field}\n  expected {}\n  observed {}",
                    expected.get(field).map_or_else(String::new, |v| v.to_string()),
                    observed.get(field).map_or_else(String::new, |v| v.to_string())
                ));
            }
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} golden field(s) differ:\n{}",
        mismatches.len(),
        mismatches.join("\n")
    );
}
